using System;using System.Collections.Generic;using System.IO;using System.IO.Pipes;using System.Linq;using System.Threading;using System.Xml;using MP1SkinStudio.Live;
class SceneProbe{
 static NamedPipeClientStream pipe;static LiveEndpoint endpoint;static string directory,epoch;static readonly List<string> results=new List<string>();
 static XmlDocument Rpc(XmlDocument d){LiveWire.Write(pipe,d);var r=LiveWire.Read(pipe);if(r.DocumentElement.GetAttribute("ok")=="false")throw new Exception(r.DocumentElement.GetAttribute("message"));return r;}
 static void Connect(){pipe=new NamedPipeClientStream(".",endpoint.Pipe,PipeDirection.InOut,PipeOptions.Asynchronous);pipe.Connect(4000);var h=LiveWire.Document("hello");LiveWire.Attr(h.DocumentElement,"nonce",endpoint.Nonce);Rpc(h);}
 static XmlDocument Snapshot(){return Rpc(LiveWire.Document("snapshot"));}static XmlElement Item(XmlDocument d,int id){return (XmlElement)d.SelectSingleNode("/live/control[@id='"+id+"']");}static string V(XmlDocument d,int id,string key){return Item(d,id).SelectSingleNode("value[@key='"+key+"']").InnerText;}
 static bool Near(XmlDocument d,int id,string key,int n){int value;return Int32.TryParse(V(d,id,key),out value)&&Math.Abs(value-n)<=1;}
 static void Check(bool c,string n){if(!c)throw new Exception(n);results.Add("PASS "+n);Console.WriteLine("PASS "+n);}static void Hold(int n){for(int i=0;i<n;i++){Rpc(LiveWire.Document("ping"));Thread.Sleep(1000);}}
 static XmlDocument Frame(XmlDocument baseline,params string[][] changes){var doc=LiveWire.Document("frame");LiveWire.Attr(doc.DocumentElement,"epoch",epoch);foreach(var change in changes){var node=LiveWire.Add(doc.DocumentElement,"control");LiveWire.Attr(node,"token",Item(baseline,Int32.Parse(change[0])).GetAttribute("token"));for(int i=1;i<change.Length;i+=2){var set=LiveWire.Add(node,"set");LiveWire.Attr(set,"key",change[i]);set.InnerText=change[i+1];}}return doc;}
 static XmlElement State(){for(int i=0;i<20;i++){try{var d=new XmlDocument{XmlResolver=null};using(var input=new FileStream(Path.Combine(directory,"special-state.xml"),FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))d.Load(input);return d.DocumentElement;}catch(IOException){Thread.Sleep(50);}}throw new IOException("Fixture observer state unavailable.");}
 static int Main(string[] args){try{directory=args[0];Directory.CreateDirectory(args[1]);Environment.SetEnvironmentVariable("MP1_SKIN_STUDIO_LIVE_DIR",directory);endpoint=LiveEndpoint.Discover().Single();Connect();var activate=LiveWire.Document("activate");LiveWire.Attr(activate.DocumentElement,"window",90120);Rpc(activate);Hold(2);var baseline=Snapshot();epoch=baseline.DocumentElement.GetAttribute("epoch");Check(baseline.DocumentElement.GetAttribute("bridgeVersion")=="1.2.0.0","full MP process loads bridge 1.2");Check(State().GetAttribute("items")=="6"&&State().GetAttribute("mode")=="small","gallery starts with six items in small mode");var frame=Frame(baseline,new[]{"21201","selected","yes","textureCheckmark","check-boxNF.png","markWidth","95","markHeight","95"},new[]{"21202","selected","no","textureCheckmarkNoFocus","check-box.png","markWidth","95","markHeight","95"},new[]{"21203","animations","<effects><animation effect='fade' time='400' start='25' end='25'>WindowOpen</animation></effects>"},new[]{"21204","itemWidth","240","textureWidth","210","thumbWidth","180"});Rpc(frame);Hold(1);var changed=Snapshot();Check(V(changed,21201,"textureCheckmark")=="check-boxNF.png"&&V(changed,21202,"textureCheckmarkNoFocus")=="check-box.png","allocated checkbox textures update in both native states");Check(Near(changed,21201,"markWidth",95)&&Near(changed,21202,"markHeight",95),"allocated checkbox images resize");Check(Near(changed,21204,"itemWidth",240)&&Near(changed,21204,"thumbWidth",180),"small gallery template updates in full renderer");Check(V(changed,21203,"animations")=="1 native effects","native effect replacement is accepted");Check(changed.DocumentElement.GetAttribute("epoch")==epoch,"control identities remain stable without page reload");Check(State().GetAttribute("items")=="6","native gallery items survive small-template rebuilding");Console.WriteLine("HOLDING small gallery and checkbox/effect preview for 18 seconds");Hold(18);var empty=LiveWire.Document("frame");LiveWire.Attr(empty.DocumentElement,"epoch",epoch);Rpc(empty);Hold(1);var restored=Snapshot();foreach(var spec in new[]{new[]{"21201","selected","textureCheckmark","markWidth","markHeight"},new[]{"21202","selected","textureCheckmarkNoFocus","markWidth","markHeight"},new[]{"21203","animations"},new[]{"21204","itemWidth","textureWidth","thumbWidth"}}){int id=Int32.Parse(spec[0]);Check(spec.Skip(1).All(key=>V(restored,id,key)==V(baseline,id,key)),"empty frame restores original fields for "+id);}
 File.WriteAllText(Path.Combine(directory,"special-mode.txt"),"big");Hold(2);Check(State().GetAttribute("mode")=="big"&&State().GetAttribute("items")=="6","native large-icon mode switch keeps all items");var big=Snapshot();var bigFrame=Frame(big,new[]{"21204","itemWidthBig","360","textureWidthBig","300","thumbWidthBig","260"});Rpc(bigFrame);Hold(1);changed=Snapshot();Check(Near(changed,21204,"itemWidthBig",360)&&Near(changed,21204,"textureWidthBig",300)&&Near(changed,21204,"thumbWidthBig",260),"large gallery templates update in full renderer");Check(State().GetAttribute("items")=="6","large-template rebuilding retains native items");Console.WriteLine("HOLDING large gallery preview for 18 seconds");Hold(18);Rpc(empty);Hold(1);restored=Snapshot();Check(new[]{"itemWidthBig","textureWidthBig","thumbWidthBig"}.All(key=>V(restored,21204,key)==V(big,21204,key)),"large templates restore exactly");Rpc(bigFrame);Rpc(LiveWire.Document("disconnect"));pipe.Dispose();Thread.Sleep(300);Connect();restored=Snapshot();Check(new[]{"itemWidthBig","textureWidthBig","thumbWidthBig"}.All(key=>V(restored,21204,key)==V(big,21204,key))&&State().GetAttribute("items")=="6","disconnect restores native gallery templates and data");Rpc(LiveWire.Document("disconnect"));Console.WriteLine(results.Count+" full-renderer special checks passed.");return 0;
 }catch(Exception ex){results.Add(ex.ToString());Console.Error.WriteLine(ex);return 1;}finally{if(pipe!=null)pipe.Dispose();Directory.CreateDirectory(args[1]);File.WriteAllLines(Path.Combine(args[1],"Results.txt"),results);}}
}
